import sys
from collections import deque

s = sys.stdin.read().split()[0]
n = len(s)
dist = {s: 0}
q = deque([s])
ans = -1
while q:
    cur = q.popleft()
    if cur == cur[::-1]:
        ans = dist[cur]
        break
    for i in range(n):
        for j in range(i + 1, n):
            if cur[i] != cur[j]:
                l = list(cur)
                l[i], l[j] = l[j], l[i]
                t = ''.join(l)
                if t not in dist:
                    dist[t] = dist[cur] + 1
                    q.append(t)
print(ans)

